import json


def export(value, ctx, **options):
    blob = ctx.write_blob(
        "summary.json",
        json.dumps(value, allow_nan=False, indent=2).encode(),
        media_type="application/json",
    )
    return {
        "format_id": "summary.json.v1",
        "media_type": "application/json",
        "data": {
            "type": "bundle",
            "files": {"data": blob},
            "entry": "data",
        },
        "metadata": {"kind": "finance-summary"},
    }

import json


def export(value, ctx, **options):
    blob = ctx.write_blob(
        "symbols-selector.json",
        json.dumps(value, allow_nan=False, indent=2).encode(),
        media_type="application/json",
    )
    return {
        "format_id": "marimo.selector-state.json.v1",
        "media_type": "application/json",
        "data": {
            "type": "bundle",
            "files": {"data": blob},
            "entry": "data",
        },
        "metadata": {"kind": "marimo-selector-state"},
    }

def export(value, ctx, **options):
    html = value.text if hasattr(value, "text") else str(value)
    blob = ctx.write_blob(
        options.get("filename", "change-desc.html"),
        html.encode("utf-8"),
        media_type="text/html",
    )
    return {
        "format_id": "marimo.cell_output.html.v1",
        "media_type": "text/html",
        "data": {
            "type": "bundle",
            "files": {"html": blob},
            "entry": "html",
        },
        "metadata": {
            "kind": "marimo-cell-output",
            "cell": "change_desc",
        },
    }

